  log_can_error(can_error);
}

s = tf('s');
G = 50 / (s^3 + 9*s^2 + 30*s + 40);

margin(G); grid on;          % 增益/相位裕度
[Gm, Pm, Wcg, Wcp] = margin(G);

T = feedback(G, 1);         % 单位负反馈闭环
closed_loop_poles = pole(T)
is_stable = isstable(T)

figure;
step(T); grid on;

typedef struct { uint32_t tick; float value; } Sample;
osMessageQueueId_t sample_queue;

void Producer(void *arg) {
    Sample sample;
    for (;;) {
        sample.tick = osKernelGetTickCount();
        sample.value = read_sensor();
        osMessageQueuePut(sample_queue, &sample, 0U, 10U);
        osDelay(10U);
    }
}

